/* MBM V12 — property-centred, zero-cost workspace. */
(()=>{'use strict';
const KEY='mbmPropertyManagerV12',VIEWS=['today','portfolio','occupancy','finance','operations','control','reports','admin'];
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],today=()=>new Date().toISOString().slice(0,10),uid=p=>`${p}_${crypto.randomUUID?.().slice(0,10)||Math.random().toString(36).slice(2)}`;
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])),money=n=>`N$ ${Number(n||0).toLocaleString('en-NA',{minimumFractionDigits:2,maximumFractionDigits:2})}`,date=v=>v?new Intl.DateTimeFormat('en-NA',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${v}T00:00:00`)):'—',days=v=>v?Math.ceil((new Date(`${v}T00:00:00`)-new Date(`${today()}T00:00:00`))/86400000):null;
const blank=()=>({version:12,organization:{name:'Musa Business Management CC',currency:'N$',timezone:'Africa/Windhoek'},regions:[],properties:[],buildings:[],floors:[],units:[],contacts:[],leases:[],renewals:[],terminations:[],charges:[],payments:[],allocations:[],municipalAccounts:[],meters:[],meterReadings:[],vendors:[],workOrders:[],inspections:[],documents:[],tasks:[],complianceItems:[],audit:[],ui:{view:'today',propertyId:'',reportScope:'',report:'portfolio'}});
function parse(raw,fallback){try{return JSON.parse(raw)||fallback}catch{return fallback}}
function migrate(){const old=parse(localStorage.getItem('mbmPropertyManagerV10'),null);if(!old)return blank();const n=Object.assign(blank(),old,{version:12});n.regions=n.regions?.length?n.regions:[{id:'region_namibia',name:'Namibia',code:'NA',createdAt:today()}];n.properties=(old.properties||[]).map(p=>({...p,regionId:p.regionId||'region_namibia',locality:p.locality||'',country:p.country||'Namibia'}));n.buildings=n.buildings?.length?n.buildings:n.properties.map(p=>({id:`building_${p.id}`,propertyId:p.id,name:'Main Building',status:'Active',createdAt:today()}));n.floors=n.floors?.length?n.floors:n.buildings.map(b=>({id:`floor_${b.id}`,buildingId:b.id,name:'Ground Floor',sequence:0,createdAt:today()}));n.units=(old.units||[]).map(u=>({...u,buildingId:u.buildingId||`building_${u.propertyId}`,floorId:u.floorId||`floor_building_${u.propertyId}`,status:u.status||'Vacant'}));n.charges=old.charges||old.invoices||[];n.renewals=old.renewals||[];n.terminations=old.terminations||[];n.meters=old.meters||[];n.meterReadings=old.meterReadings||[];n.complianceItems=old.complianceItems||[];n.ui={...blank().ui,...old.ui,view:'today'};return n}
let state=parse(localStorage.getItem(KEY),null)||migrate();
function save(msg='Saved locally'){localStorage.setItem(KEY,JSON.stringify(state));$('#saveStatus').textContent=msg;setTimeout(()=>$('#saveStatus').textContent='Local workspace',2200)}
function audit(action,detail){state.audit.unshift({id:uid('audit'),at:new Date().toISOString(),action,detail})}
const find=(a,id)=>state[a].find(x=>x.id===id),prop=id=>find('properties',id),unit=id=>find('units',id),contact=id=>find('contacts',id),lease=id=>find('leases',id),building=id=>find('buildings',id),floor=id=>find('floors',id),vendor=id=>find('vendors',id);
const propertyName=id=>{const p=prop(id);return p?`${p.code||'Property'} · ${p.name}`:'—'},unitName=id=>{const u=unit(id);return u?u.name:'—'},leaseName=id=>{const l=lease(id);return l?`${l.leaseNo||'Agreement'} · ${contact(l.contactId)?.name||'Resident'}`:'—'};
const active=l=>['Active','Signed','Renewal in progress'].includes(l.status),openCharge=c=>Math.max(0,Number(c.amount||0)-state.allocations.filter(a=>a.chargeId===c.id).reduce((s,a)=>s+Number(a.amount||0),0)),openCharges=()=>state.charges.filter(c=>openCharge(c)>.009),activeLeases=()=>state.leases.filter(active),due=()=>activeLeases().reduce((s,l)=>s+Number(l.monthlyRent||0),0),received=()=>state.payments.filter(p=>String(p.paymentDate).slice(0,7)===today().slice(0,7)).reduce((s,p)=>s+Number(p.amount||0),0),municipal=()=>state.municipalAccounts.reduce((s,m)=>s+Number(m.balance||0),0);
function issues(){const a=[];state.leases.filter(l=>active(l)&&(!l.endDate||days(l.endDate)<=90)).forEach(l=>a.push({level:!l.endDate||days(l.endDate)<0?'red':'gold',kind:'Agreement',name:leaseName(l.id),text:!l.endDate?'Active agreement has no expiry date':`${days(l.endDate)} days to expiry`}));openCharges().filter(c=>c.dueDate&&days(c.dueDate)<0).forEach(c=>a.push({level:'red',kind:'Arrears',name:leaseName(c.leaseId),text:`${money(openCharge(c))} overdue`}));state.municipalAccounts.filter(m=>m.dueDate&&days(m.dueDate)<0&&Number(m.balance)>0).forEach(m=>a.push({level:'red',kind:'Municipal',name:propertyName(m.propertyId),text:`${money(m.balance)} overdue`}));state.workOrders.filter(w=>w.dueDate&&days(w.dueDate)<0&&!['Closed','Completed'].includes(w.status)).forEach(w=>a.push({level:'red',kind:'Service',name:w.title,text:'Work order overdue'}));state.inspections.filter(i=>i.date&&days(i.date)<0&&!['Completed','Closed'].includes(i.status)).forEach(i=>a.push({level:'red',kind:'Inspection',name:propertyName(i.propertyId),text:'Inspection overdue'}));state.complianceItems.filter(c=>c.dueDate&&days(c.dueDate)<0&&c.status!=='Closed').forEach(c=>a.push({level:'red',kind:'Compliance',name:c.title,text:'Compliance action overdue'}));return a}
const badge=(x,l='grey')=>`<span class="badge ${l}">${esc(x)}</span>`,empty=(n,t)=>`<tr><td colspan="${n}"><div class="empty">${t}</div></td></tr>`,head=(t,d,a='')=>`<div class="view-head"><div><h2>${t}</h2><p>${d}</p></div><div class="view-actions">${a}</div></div>`;
function render(){const v=VIEWS.includes(state.ui.view)?state.ui.view:'today';state.ui.view=v;$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===v));const meta={today:['MBM WORKSPACE','Today'],portfolio:['PORTFOLIO','Portfolio 360°'],occupancy:['OCCUPANCY','Agreements & lifecycle'],finance:['REVENUE','Revenue & municipal'],operations:['OPERATIONS','Service & inspections'],control:['CONTROL','Control Centre'],reports:['INSIGHTS','Insights & reports'],admin:['SETTINGS','Settings & security']}[v];$('#eyebrow').textContent=meta[0];$('#pageTitle').textContent=meta[1];$('#app').innerHTML=({today:todayView,portfolio:portfolioView,occupancy:occupancyView,finance:financeView,operations:operationsView,control:controlView,reports:reportsView,admin:adminView}[v])();wireFilters()}
function todayView(){const occ=state.units.length?Math.round(state.units.filter(u=>u.status==='Occupied').length/state.units.length*100):0,all=issues();return `${head('Today','Your live management queue. MBM generates priorities from connected property records.',`<button class="secondary" data-action="form" data-type="task">Add task</button><button class="primary" data-action="form" data-type="property">Add property</button>`)}<section class="mbm-hero"><div><span class="eyebrow">MUSA BUSINESS MANAGEMENT CC</span><h2>One connected property workspace.</h2><p>Property → building → floor → unit → agreement → money → service → control.</p></div><div class="hero-steps"><span>Properties</span><span>Agreements</span><span>Revenue</span><span>Service</span></div></section><div class="kpis"><div class="kpi"><label>Properties / units</label><strong>${state.properties.length} / ${state.units.length}</strong><small>${occ}% occupancy</small></div><div class="kpi"><label>Expected monthly revenue</label><strong>${money(due())}</strong><small>${activeLeases().length} active agreements</small></div><div class="kpi ${openCharges().length?'warn':''}"><label>Open debt</label><strong>${money(openCharges().reduce((s,c)=>s+openCharge(c),0))}</strong><small>Charges less allocations</small></div><div class="kpi ${municipal()?'danger':''}"><label>Municipal balance</label><strong>${money(municipal())}</strong><small>${state.municipalAccounts.length} account(s)</small></div></div><div class="grid two"><section class="panel"><div class="panel-head"><h3>Priority actions</h3><button class="link-button" data-view="control">Open control</button></div><div class="panel-body"><ul class="action-list">${all.slice(0,8).map(i=>`<li><div><b>${esc(i.kind)} · ${esc(i.name)}</b><span>${esc(i.text)}</span></div>${badge(i.level==='red'?'Act now':'Review',i.level)}</li>`).join('')||'<li><span>No monitored exceptions. Keep records current.</span></li>'}</ul></div></section><section class="panel"><div class="panel-head"><h3>Lifecycle guide</h3></div><div class="panel-body"><ol class="guide-list"><li>Register the portfolio hierarchy once.</li><li>Link residents to an existing unit through an agreement.</li><li>Record charges, payments, municipal balances and meters.</li><li>Control service, inspections, compliance, renewal or exit.</li><li>Use reports for management decisions.</li></ol></div></section></div>`}
function portfolioView(){const pid=state.properties.some(p=>p.id===state.ui.propertyId)?state.ui.propertyId:state.properties[0]?.id||'',p=prop(pid),builds=state.buildings.filter(b=>b.propertyId===pid),units=state.units.filter(u=>u.propertyId===pid);return `${head('Portfolio 360°','The only place property hierarchy is created. Other workspaces select these records; they do not recreate them.',`<button class="secondary" data-action="form" data-type="region">Add region</button><button class="primary" data-action="form" data-type="property">Add property</button>`)}<section class="scope-bar"><div><label>Property 360°</label><select id="propertyScope"><option value="">Select a property</option>${state.properties.map(x=>`<option value="${x.id}" ${x.id===pid?'selected':''}>${esc(propertyName(x.id))}</option>`).join('')}</select></div>${p?`<div class="scope-address"><b>${esc(p.name)}</b><span>${esc(p.address||'No address set')} · ${esc(p.locality||'Location to be completed')}</span></div><button class="secondary" data-action="map" data-id="${p.id}">Map</button>`:''}</section>${p?`<div class="kpis compact"><div class="kpi"><label>Buildings</label><strong>${builds.length}</strong><small>Property structure</small></div><div class="kpi"><label>Floors</label><strong>${state.floors.filter(f=>builds.some(b=>b.id===f.buildingId)).length}</strong><small>Across this property</small></div><div class="kpi"><label>Units</label><strong>${units.length}</strong><small>${units.filter(u=>u.status==='Occupied').length} occupied</small></div><div class="kpi"><label>Property location</label><strong>${p.latitude?'Set':'Pending'}</strong><small>${p.latitude?`${Number(p.latitude).toFixed(4)}, ${Number(p.longitude).toFixed(4)}`:'Use address assist'}</small></div></div>`:''}<div class="grid two"><section class="panel"><div class="panel-head"><h3>Property register</h3><span>${state.properties.length} record(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Region / property</th><th>Address</th><th>Type</th><th>Location</th><th></th></tr></thead><tbody>${state.properties.map(x=>`<tr class="${x.id===pid?'selected-row':''}"><td><span class="main">${esc(find('regions',x.regionId)?.name||'Unassigned')}</span><span class="sub">${esc(x.code)} · ${esc(x.name)}</span></td><td>${esc(x.address||'—')}</td><td>${esc(x.type)}</td><td>${x.latitude?'GPS set':'Pending'}</td><td><button class="link-button" data-action="select-property" data-id="${x.id}">Open</button> · <button class="link-button" data-action="form" data-type="property" data-id="${x.id}">Edit</button></td></tr>`).join('')||empty(5,'Start by adding a region and property.')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Hierarchy at selected property</h3>${p?`<button class="secondary" data-action="form" data-type="building" data-property="${pid}">Add building</button>`:''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Building / floor / unit</th><th>Type</th><th>Status</th><th>Market rent</th><th></th></tr></thead><tbody>${units.map(u=>`<tr><td><span class="main">${esc(building(u.buildingId)?.name||'Main building')} · ${esc(floor(u.floorId)?.name||'Ground floor')}</span><span class="sub">${esc(u.name)}</span></td><td>${esc(u.type)}</td><td>${badge(u.status,u.status==='Occupied'?'blue':u.status==='Vacant'?'gold':'grey')}</td><td>${money(u.marketRent)}</td><td><button class="link-button" data-action="form" data-type="unit" data-id="${u.id}">Edit</button></td></tr>`).join('')||empty(5,'Add building, floor and unit for this property.')}</tbody></table></div></section></div>`}
function occupancyView(){return `${head('Occupancy & agreements','Manage the resident lifecycle: prospect/contact → agreement → renewal or termination → unit availability.',`<button class="secondary" data-action="form" data-type="contact">Add contact</button><button class="secondary" data-action="form" data-type="termination">Start termination</button><button class="primary" data-action="form" data-type="lease">Create agreement</button>`)}<div class="kpis compact"><div class="kpi"><label>Active agreements</label><strong>${activeLeases().length}</strong><small>Current occupancy</small></div><div class="kpi"><label>Vacant units</label><strong>${state.units.filter(u=>u.status==='Vacant').length}</strong><small>Available inventory</small></div><div class="kpi warn"><label>Expiring ≤90 days</label><strong>${activeLeases().filter(l=>l.endDate&&days(l.endDate)<=90).length}</strong><small>Renewal / exit decision</small></div><div class="kpi"><label>Open terminations</label><strong>${state.terminations.filter(t=>t.stage!=='Closed').length}</strong><small>Exit workflow</small></div></div><section class="panel"><div class="panel-head"><h3>Agreement register</h3><span>Tenant, unit, term, renewal and exit in one view</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Resident / agreement</th><th>Property / unit</th><th>Expiry</th><th>Rent</th><th>Status</th><th>Next lifecycle action</th><th></th></tr></thead><tbody>${state.leases.map(l=>{const r=state.renewals.find(x=>x.leaseId===l.id),t=state.terminations.find(x=>x.leaseId===l.id);return `<tr><td><span class="main">${esc(contact(l.contactId)?.name||'—')}</span><span class="sub">${esc(l.leaseNo)}</span></td><td>${esc(propertyName(l.propertyId))}<span class="sub">${esc(unitName(l.unitId))}</span></td><td>${date(l.endDate)}<span class="sub">${l.endDate?`${days(l.endDate)} days`:''}</span></td><td>${money(l.monthlyRent)}</td><td>${badge(l.status,l.status==='Active'?'green':'grey')}</td><td>${t?badge(t.stage,t.stage==='Closed'?'green':'gold'):r?badge(r.stage,'gold'):'—'}</td><td><button class="link-button" data-action="form" data-type="lease" data-id="${l.id}">Open</button> · <button class="link-button" data-action="form" data-type="renewal" data-id="${r?.id||''}" data-lease="${l.id}">Renewal</button></td></tr>`}).join('')||empty(7,'Create the portfolio hierarchy, then add the first agreement.')}</tbody></table></div></section><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Termination & unit-turn register</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>Agreement</th><th>Reason</th><th>Notice / exit</th><th>Stage</th><th>Deposit / final balance</th><th></th></tr></thead><tbody>${state.terminations.map(t=>`<tr><td class="main">${esc(leaseName(t.leaseId))}</td><td>${esc(t.reason)}</td><td>${date(t.noticeDate)} / ${date(t.exitDate)}</td><td>${badge(t.stage,t.stage==='Closed'?'green':'gold')}</td><td>${money(t.depositDeduction)} / ${money(t.finalBalance)}</td><td><button class="link-button" data-action="form" data-type="termination" data-id="${t.id}">Open</button></td></tr>`).join('')||empty(6,'Start termination from the agreement when an exit is required.')}</tbody></table></div></section>`}
function financeView(){const mrows=state.municipalAccounts.map(m=>`<tr><td class="main">${esc(propertyName(m.propertyId))}</td><td>${esc(m.accountNo)}</td><td>${esc(m.category||'General')}</td><td>${date(m.dueDate)}</td><td>${money(m.balance)}</td><td><button class="link-button" data-action="form" data-type="municipal" data-id="${m.id}">Open</button></td></tr>`).join('');return `${head('Revenue & municipal','Revenue flows from agreements; municipal accounts and meters attach to the property. MBM keeps the financial trail linked.',`<button class="secondary" data-action="form" data-type="meter">Add meter</button><button class="secondary" data-action="form" data-type="charge">Create charge</button><button class="primary" data-action="form" data-type="payment">Receive payment</button>`)}<div class="kpis compact"><div class="kpi"><label>Expected monthly revenue</label><strong>${money(due())}</strong><small>Active agreements</small></div><div class="kpi"><label>Received this month</label><strong>${money(received())}</strong><small>${state.payments.filter(p=>String(p.paymentDate).slice(0,7)===today().slice(0,7)).length} receipts</small></div><div class="kpi warn"><label>Outstanding debt</label><strong>${money(openCharges().reduce((s,c)=>s+openCharge(c),0))}</strong><small>Open billed balance</small></div><div class="kpi danger"><label>Municipal balance</label><strong>${money(municipal())}</strong><small>Latest account statements</small></div></div><div class="grid two"><section class="panel"><div class="panel-head"><h3>Charges / collections</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>Agreement</th><th>Type</th><th>Due</th><th>Charge</th><th>Open</th><th></th></tr></thead><tbody>${openCharges().map(c=>`<tr><td class="main">${esc(leaseName(c.leaseId))}</td><td>${esc(c.type)}</td><td>${date(c.dueDate)}</td><td>${money(c.amount)}</td><td>${money(openCharge(c))}</td><td><button class="link-button" data-action="form" data-type="payment">Receive</button></td></tr>`).join('')||empty(6,'Create rent, utility, parking or ad-hoc charges against an agreement.')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Receipts</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>Receipt</th><th>Agreement</th><th>Date</th><th>Method</th><th>Amount</th><th></th></tr></thead><tbody>${state.payments.slice().sort((a,b)=>String(b.paymentDate).localeCompare(String(a.paymentDate))).map(p=>`<tr><td class="main">${esc(p.receiptNo)}</td><td>${esc(leaseName(p.leaseId))}</td><td>${date(p.paymentDate)}</td><td>${esc(p.method)}</td><td>${money(p.amount)}</td><td><button class="link-button" data-action="receipt" data-id="${p.id}">Print</button> · <button class="link-button" data-action="whatsapp" data-id="${p.id}">WhatsApp</button></td></tr>`).join('')||empty(6,'Record payments to generate receipt history.')}</tbody></table></div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Municipal accounts and meters</h3><button class="secondary" data-action="form" data-type="municipal">Add account</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Property</th><th>Account</th><th>Category</th><th>Due</th><th>Balance</th><th></th></tr></thead><tbody>${mrows||empty(6,'Add rates, water, electricity, refuse or sewerage account.')}</tbody></table></div><div class="panel-body"><div class="list-kpi"><span>Registered meters</span><strong>${state.meters.length}</strong></div><div class="list-kpi"><span>Latest consumption records</span><strong>${state.meterReadings.length}</strong></div><button class="secondary" data-action="form" data-type="meter-reading">Record meter reading</button></div></section>`}
function operationsView(){return `${head('Service & inspections','Manage the full property service cycle: request → approval → assignment → work → verification → closure.',`<button class="secondary" data-action="form" data-type="vendor">Add contractor</button><button class="secondary" data-action="form" data-type="inspection">Schedule inspection</button><button class="primary" data-action="form" data-type="work">Create work order</button>`)}<div class="grid two"><section class="panel"><div class="panel-head"><h3>Work orders</h3><span>${state.workOrders.filter(w=>!['Closed','Completed'].includes(w.status)).length} open</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Work order</th><th>Contractor</th><th>Due</th><th>Cost</th><th>Workflow</th><th></th></tr></thead><tbody>${state.workOrders.map(w=>`<tr><td><span class="main">${esc(w.title)}</span><span class="sub">${esc(propertyName(w.propertyId))} · ${esc(unitName(w.unitId))}</span></td><td>${esc(vendor(w.vendorId)?.name||w.assignee||'Unassigned')}</td><td>${date(w.dueDate)}</td><td>${money(w.actualCost)}<span class="sub">Quote ${money(w.quotedAmount)}</span></td><td>${badge(w.status,w.status==='Closed'?'green':w.priority==='Urgent'?'red':'gold')}</td><td><button class="link-button" data-action="advance-work" data-id="${w.id}">Advance</button> · <button class="link-button" data-action="form" data-type="work" data-id="${w.id}">Open</button></td></tr>`).join('')||empty(6,'Create a work order from a request or inspection defect.')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>Inspections & defects</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>Inspection</th><th>Property / unit</th><th>Date</th><th>Condition</th><th>Status</th><th></th></tr></thead><tbody>${state.inspections.map(i=>`<tr><td class="main">${esc(i.type)}</td><td>${esc(propertyName(i.propertyId))}<span class="sub">${esc(unitName(i.unitId))}</span></td><td>${date(i.date)}</td><td>${esc(i.conditionRating||'Not rated')}</td><td>${badge(i.status,i.status==='Completed'?'green':'gold')}</td><td><button class="link-button" data-action="defect-work" data-id="${i.id}">Create work</button> · <button class="link-button" data-action="form" data-type="inspection" data-id="${i.id}">Open</button></td></tr>`).join('')||empty(6,'Schedule move-in, routine, renewal, exit or compliance inspections.')}</tbody></table></div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Contractor register</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>Contractor</th><th>Trade</th><th>Contact</th><th>Certification / expiry</th><th>Status</th><th></th></tr></thead><tbody>${state.vendors.map(v=>`<tr><td class="main">${esc(v.name)}</td><td>${esc(v.trade)}</td><td>${esc(v.phone||v.email||'—')}</td><td>${date(v.certExpiry)}</td><td>${badge(v.status,v.status==='Preferred'?'green':'grey')}</td><td><button class="link-button" data-action="form" data-type="vendor" data-id="${v.id}">Open</button></td></tr>`).join('')||empty(6,'Add approved electrical, plumbing, cleaning, security or construction contractors.')}</tbody></table></div></section>`}
function controlView(){const items=[...state.tasks.map(x=>({date:x.date,label:x.title,kind:'Task',level:x.priority==='Urgent'?'red':'blue'})),...state.renewals.map(x=>({date:x.nextActionDate,label:`Renewal: ${leaseName(x.leaseId)}`,kind:'Agreement',level:'gold'})),...state.complianceItems.map(x=>({date:x.dueDate,label:x.title,kind:'Compliance',level:'red'})),...state.inspections.map(x=>({date:x.date,label:`Inspection: ${propertyName(x.propertyId)}`,kind:'Inspection',level:'blue'}))].filter(x=>x.date).sort((a,b)=>a.date.localeCompare(b.date));return `${head('Control Centre','All deadlines, documents, compliance, approvals and tasks appear here from their source record.',`<button class="secondary" data-action="form" data-type="compliance">Add compliance item</button><button class="secondary" data-action="form" data-type="document">Register document</button><button class="primary" data-action="form" data-type="task">Add task</button>`)}<div class="grid two"><section class="panel"><div class="panel-head"><h3>Control calendar</h3></div><div class="panel-body"><ul class="action-list">${items.slice(0,30).map(i=>`<li><div><b>${esc(i.label)}</b><span>${date(i.date)} · ${esc(i.kind)}</span></div>${badge(days(i.date)<0?'Overdue':`${days(i.date)} days`,days(i.date)<0?'red':i.level)}</li>`).join('')||'<li><span>No dates recorded.</span></li>'}</ul></div></section><section class="panel"><div class="panel-head"><h3>Compliance findings</h3></div><div class="panel-body"><ul class="action-list">${issues().map(i=>`<li><div><b>${esc(i.kind)} · ${esc(i.name)}</b><span>${esc(i.text)}</span></div>${badge(i.level==='red'?'Action required':'Review',i.level)}</li>`).join('')||'<li><span>All monitored controls are clear.</span></li>'}</ul></div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Document register</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>Document</th><th>Property / agreement</th><th>Status</th><th>Review</th><th>Reference</th><th></th></tr></thead><tbody>${state.documents.map(d=>`<tr><td><span class="main">${esc(d.name)}</span><span class="sub">${esc(d.type)}</span></td><td>${esc(propertyName(d.propertyId||lease(d.leaseId)?.propertyId))}<span class="sub">${esc(leaseName(d.leaseId))}</span></td><td>${badge(d.status,d.status==='Current'?'green':'grey')}</td><td>${date(d.expiryDate)}</td><td>${esc(d.fileName||'Register only')}</td><td><button class="link-button" data-action="form" data-type="document" data-id="${d.id}">Open</button></td></tr>`).join('')||empty(6,'Register title deeds, plans, leases, notices, reports, statements and evidence.')}</tbody></table></div></section>`}
function reportsView(){const scope=state.ui.reportScope,leaseScope=l=>!scope||l.propertyId===scope;return `${head('Insights & reports','Live reporting from connected records. Select a property to create a focused management pack.',`<button class="secondary" data-action="export-report">Export current report</button><button class="primary" data-action="backup">Download backup</button>`)}<section class="scope-bar"><div><label>Report scope</label><select id="reportScope"><option value="">Entire portfolio</option>${state.properties.map(p=>`<option value="${p.id}" ${p.id===scope?'selected':''}>${esc(propertyName(p.id))}</option>`).join('')}</select></div><div class="scope-address"><b>${scope?esc(propertyName(scope)):'Entire portfolio'}</b><span>Reports calculate from the same operational records.</span></div></section><div class="report-actions"><button class="secondary" data-report="portfolio">Portfolio</button><button class="secondary" data-report="revenue">Revenue & arrears</button><button class="secondary" data-report="agreements">Agreements & renewals</button><button class="secondary" data-report="operations">Operations</button><button class="secondary" data-report="compliance">Compliance</button><button class="secondary" data-report="municipal">Municipal / meters</button></div>${reportTable(state.ui.report||'portfolio',scope,leaseScope)}`}
function reportTable(r,scope,leaseScope){let h=[],rows=[];if(r==='portfolio'){h=['Property','Buildings','Units','Occupied','Vacant'];rows=state.properties.filter(p=>!scope||p.id===scope).map(p=>{const u=state.units.filter(x=>x.propertyId===p.id);return[propertyName(p.id),state.buildings.filter(b=>b.propertyId===p.id).length,u.length,u.filter(x=>x.status==='Occupied').length,u.filter(x=>x.status==='Vacant').length]})}if(r==='revenue'){h=['Agreement','Contracted rent','Charged','Paid','Open'];rows=state.leases.filter(leaseScope).map(l=>[leaseName(l.id),money(l.monthlyRent),money(state.charges.filter(c=>c.leaseId===l.id).reduce((s,c)=>s+Number(c.amount||0),0)),money(state.payments.filter(p=>p.leaseId===l.id).reduce((s,p)=>s+Number(p.amount||0),0)),money(openCharges().filter(c=>c.leaseId===l.id).reduce((s,c)=>s+openCharge(c),0))])}if(r==='agreements'){h=['Agreement','Property / unit','Expiry','Days','Renewal / termination'];rows=state.leases.filter(leaseScope).map(l=>[leaseName(l.id),`${propertyName(l.propertyId)} · ${unitName(l.unitId)}`,date(l.endDate),l.endDate?days(l.endDate):'—',state.terminations.find(t=>t.leaseId===l.id)?.stage||state.renewals.find(x=>x.leaseId===l.id)?.stage||'—'])}if(r==='operations'){h=['Work / inspection','Property','Date','Status','Cost / condition'];rows=[...state.workOrders.filter(w=>!scope||w.propertyId===scope).map(w=>[`Work: ${w.title}`,propertyName(w.propertyId),date(w.dueDate),w.status,money(w.actualCost)]),...state.inspections.filter(i=>!scope||i.propertyId===scope).map(i=>[`Inspection: ${i.type}`,propertyName(i.propertyId),date(i.date),i.status,i.conditionRating||'—'])]}if(r==='compliance'){h=['Control','Record','Due','Status'];rows=[...issues().map(i=>[i.kind,i.name,'—',i.text]),...state.complianceItems.filter(c=>!scope||c.propertyId===scope).map(c=>['Compliance',c.title,date(c.dueDate),c.status])]}if(r==='municipal'){h=['Property','Account / meter','Category','Balance / consumption','Due / reading'];rows=[...state.municipalAccounts.filter(m=>!scope||m.propertyId===scope).map(m=>[propertyName(m.propertyId),m.accountNo,m.category,money(m.balance),date(m.dueDate)]),...state.meters.filter(m=>!scope||m.propertyId===scope).map(m=>[propertyName(m.propertyId),m.meterNo,m.type,`${state.meterReadings.filter(x=>x.meterId===m.id).slice(-1)[0]?.consumption||0} units`,date(state.meterReadings.filter(x=>x.meterId===m.id).slice(-1)[0]?.readingDate)])]};return `<section class="panel" style="margin-top:18px"><div class="panel-head"><h3>${esc(r)} report</h3><span>${rows.length} record(s)</span></div><div class="table-wrap"><table class="table"><thead><tr>${h.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr>${x.map((c,i)=>`<td class="${i===0?'main':''}">${esc(c)}</td>`).join('')}</tr>`).join('')||empty(h.length,'No records in this report scope.')}</tbody></table></div></section>`}
function adminView(){return `${head('Settings & security','Control backup, private cloud copy, roles and audit history.',`<button class="primary" data-action="backup">Download backup</button>`)}<div class="grid equal"><section class="panel"><div class="panel-head"><h3>Cloud backup</h3></div><div class="panel-body"><div class="status-bar">Use the browser-safe Supabase connection already configured for private backup. This is not a multi-user relational deployment yet.</div><div class="view-actions"><button class="secondary" data-action="cloud-signin">Sign in</button><button class="secondary" data-action="cloud-signup">Create account</button><button class="primary" data-action="cloud-save">Save to cloud</button><button class="secondary" data-action="cloud-load">Load cloud copy</button><button class="secondary" data-action="import">Import backup</button></div></div></section><section class="panel"><div class="panel-head"><h3>Audit & security</h3></div><div class="panel-body"><div class="list-kpi"><span>Activity events</span><strong>${state.audit.length}</strong></div><div class="list-kpi"><span>Roles staged</span><strong>Property · Finance · Facilities · Compliance · Admin</strong></div><div class="list-kpi"><span>Current model</span><strong>Private browser workspace + backup</strong></div></div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>Recent activity</h3></div><div class="table-wrap"><table class="table"><thead><tr><th>When</th><th>Action</th><th>Detail</th></tr></thead><tbody>${state.audit.slice(0,30).map(a=>`<tr><td>${new Date(a.at).toLocaleString('en-NA')}</td><td class="main">${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`).join('')||empty(3,'Activity appears here when data is created or changed.')}</tbody></table></div></section>`}
const opt=(name,label,value,items,none='Select…')=>`<div class="field"><label>${label}</label><select name="${name}"><option value="">${none}</option>${items.map(x=>{const v=typeof x==='object'?x.value:x,l=typeof x==='object'?x.label:x;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select></div>`,inp=(name,label,value='',type='text')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}"></div>`,txt=(name,label,value='')=>`<div class="field span2"><label>${label}</label><textarea name="${name}">${esc(value)}</textarea></div>`;
function formHtml(t,r={},extra={}){const regions=state.regions.map(x=>({value:x.id,label:x.name})),properties=state.properties.map(x=>({value:x.id,label:propertyName(x.id)})),buildings=state.buildings.map(x=>({value:x.id,label:`${propertyName(x.propertyId)} · ${x.name}`})),floors=state.floors.map(x=>({value:x.id,label:`${building(x.buildingId)?.name||'Building'} · ${x.name}`})),units=state.units.map(x=>({value:x.id,label:`${propertyName(x.propertyId)} · ${x.name}`})),contacts=state.contacts.map(x=>({value:x.id,label:`${x.name} · ${x.role||'Contact'}`})),leases=state.leases.map(x=>({value:x.id,label:leaseName(x.id)})),vendors=state.vendors.map(x=>({value:x.id,label:`${x.name} · ${x.trade||'General'}`})),meters=state.meters.map(x=>({value:x.id,label:`${propertyName(x.propertyId)} · ${x.meterNo}`}));
if(t==='region')return `<div class="form-grid">${inp('name','Region name',r.name)}${inp('code','Region code',r.code)}${txt('notes','Notes',r.notes)}</div>`;
if(t==='property')return `<div class="form-grid">${opt('regionId','Region',r.regionId||'',regions)}${inp('code','Property number / ERF code',r.code)}${inp('name','Property name',r.name)}${inp('erf','ERF / title reference',r.erf)}<div class="field span2"><label>Address</label><div class="location-entry"><input id="propertyAddress" name="address" autocomplete="off" value="${esc(r.address||'')}" placeholder="Start typing an address, suburb or town"><button type="button" class="secondary" id="useCurrentLocation">Use my location</button></div><div id="addressSuggestions" class="address-suggestions"></div><p class="form-help">Free OpenStreetMap suggestions after three characters.</p></div>${inp('locality','Suburb / town',r.locality)}${inp('country','Country',r.country||'Namibia')}${opt('type','Property type',r.type||'Residential',['Residential','Commercial','Mixed Use','Industrial','Land'])}${opt('status','Status',r.status||'Active',['Active','Inactive','Archived'])}${inp('latitude','Latitude',r.latitude)}${inp('longitude','Longitude',r.longitude)}${inp('photoName','Property photo reference',r.photoName)}${txt('notes','Property notes',r.notes)}</div>`;
if(t==='building')return `<div class="form-grid">${opt('propertyId','Property',r.propertyId||extra.propertyId||'',properties)}${inp('name','Building name',r.name)}${inp('code','Building code',r.code)}${opt('status','Status',r.status||'Active',['Active','Inactive'])}${txt('notes','Building notes',r.notes)}</div>`;
if(t==='floor')return `<div class="form-grid">${opt('buildingId','Building',r.buildingId||extra.buildingId||'',buildings)}${inp('name','Floor name',r.name)}${inp('sequence','Floor sequence',r.sequence,'number')}${txt('notes','Floor notes',r.notes)}</div>`;
if(t==='unit')return `<div class="form-grid">${opt('propertyId','Property',r.propertyId||extra.propertyId||'',properties)}${opt('buildingId','Building',r.buildingId||'',buildings)}${opt('floorId','Floor',r.floorId||'',floors)}${inp('name','Unit / rental area',r.name)}${opt('type','Unit type',r.type||'Rental Unit',['Rental Unit','Office','Shop','Warehouse','Parking','Common Area','Land'])}${opt('status','Occupancy status',r.status||'Vacant',['Vacant','Occupied','Reserved','Under Maintenance','Unavailable'])}${inp('marketRent','Monthly market rent',r.marketRent,'number')}${inp('area','Area m²',r.area,'number')}${txt('notes','Unit notes',r.notes)}</div>`;
if(t==='contact')return `<div class="form-grid">${inp('name','Full / legal name',r.name)}${opt('role','Contact role',r.role||'Tenant',['Tenant','Owner','Prospect','Guarantor','Other'])}${inp('phone','Phone / WhatsApp',r.phone)}${inp('email','Email',r.email,'email')}${inp('idNo','ID / registration no.',r.idNo)}${txt('notes','Contact notes',r.notes)}</div>`;
if(t==='lease')return `<div class="form-grid">${inp('leaseNo','Agreement reference',r.leaseNo)}${opt('contactId','Resident / tenant',r.contactId||'',contacts)}${opt('propertyId','Property',r.propertyId||'',properties)}${opt('unitId','Unit',r.unitId||'',units)}${inp('startDate','Start date',r.startDate,'date')}${inp('endDate','Expiry date',r.endDate,'date')}${inp('monthlyRent','Monthly contractual rent',r.monthlyRent,'number')}${inp('escalation','Annual escalation %',r.escalation||0,'number')}${inp('deposit','Security deposit',r.deposit||0,'number')}${inp('noticeDays','Notice days',r.noticeDays||60,'number')}${opt('status','Agreement status',r.status||'Draft',['Draft','Pending Approval','Active','Signed','Renewal in progress','Terminated'])}${txt('notes','Agreement notes / amendment reference',r.notes)}</div>`;
if(t==='renewal')return `<div class="form-grid">${opt('leaseId','Agreement',r.leaseId||extra.leaseId||'',leases)}${opt('stage','Renewal stage',r.stage||'Expiry review',['Expiry review','Notice issued','Negotiation','Legal review','Management approval','Awaiting signature','Renewed / billing activated','Non-renewal / exit'])}${inp('nextActionDate','Next action',r.nextActionDate,'date')}${inp('noticeDate','Notice date',r.noticeDate,'date')}${inp('proposedRent','Proposed rent',r.proposedRent,'number')}${inp('termMonths','New term (months)',r.termMonths||12,'number')}${opt('approvalStatus','Approval',r.approvalStatus||'Pending',['Pending','Approved','Rejected'])}${inp('agreementRef','New agreement reference',r.agreementRef)}${inp('signatureDate','Signature date',r.signatureDate,'date')}${txt('notes','Negotiation / legal notes',r.notes)}</div>`;
if(t==='termination')return `<div class="form-grid">${opt('leaseId','Agreement',r.leaseId||'',leases)}${opt('reason','Termination reason',r.reason||'Natural Expiry',['Natural Expiry','Early Termination','Mutual Agreement','Breach of Contract','Eviction','Relocation'])}${inp('noticeDate','Notice date',r.noticeDate,'date')}${inp('exitDate','Termination / exit date',r.exitDate,'date')}${opt('stage','Exit stage',r.stage||'Requested',['Requested','Approval','Exit inspection scheduled','Inspection completed','Damage assessment','Deposit reconciliation','Financial clearance','Closed'])}${inp('depositDeduction','Deposit deduction',r.depositDeduction||0,'number')}${inp('finalBalance','Final balance',r.finalBalance||0,'number')}${opt('approvalStatus','Approval',r.approvalStatus||'Pending',['Pending','Approved','Rejected'])}${txt('notes','Supporting documents / notes',r.notes)}</div>`;
if(t==='charge')return `<div class="form-grid">${opt('leaseId','Agreement',r.leaseId||'',leases)}${opt('type','Charge type',r.type||'Rent',['Rent','Utilities','Water','Electricity','Parking','Deposit','Late fee','Additional service','Other'])}${inp('chargeDate','Charge date',r.chargeDate||today(),'date')}${inp('dueDate','Due date',r.dueDate||today(),'date')}${inp('description','Description',r.description)}${inp('amount','Amount',r.amount,'number')}${txt('notes','Notes',r.notes)}</div>`;
if(t==='payment')return `<div class="form-grid">${opt('leaseId','Agreement',r.leaseId||'',leases)}${opt('chargeId','Allocate to charge',r.chargeId||'',openCharges().map(c=>({value:c.id,label:`${leaseName(c.leaseId)} · ${money(openCharge(c))}`})),'Leave unallocated')}${inp('receiptNo','Receipt number',r.receiptNo||`MBM-${today().replaceAll('-','')}-${String(state.payments.length+1).padStart(3,'0')}`)}${inp('paymentDate','Payment date',r.paymentDate||today(),'date')}${inp('period','Payment period',r.period||'')}${inp('amount','Amount received',r.amount,'number')}${opt('method','Method',r.method||'EFT',['EFT','Cash','Bank Transfer','Bank Deposit','Card','Other'])}${txt('notes','Receipt notes',r.notes)}</div>`;
if(t==='municipal')return `<div class="form-grid">${opt('propertyId','Property',r.propertyId||'',properties)}${inp('accountNo','Account number',r.accountNo)}${opt('category','Charge category',r.category||'Rates and Taxes',['Rates and Taxes','Water','Electricity','Refuse Removal','Sewerage Charges','General'])}${inp('statementDate','Statement date',r.statementDate,'date')}${inp('dueDate','Due date',r.dueDate,'date')}${inp('balance','Current amount owing',r.balance,'number')}${txt('notes','Statement reference / notes',r.notes)}</div>`;
if(t==='meter')return `<div class="form-grid">${opt('propertyId','Property',r.propertyId||'',properties)}${opt('unitId','Unit (optional)',r.unitId||'',units,'Property-level meter')}${opt('type','Meter type',r.type||'Water',['Water','Electricity'])}${inp('meterNo','Meter number',r.meterNo)}${inp('installDate','Installation date',r.installDate,'date')}${opt('status','Status',r.status||'Active',['Active','Inactive','Removed'])}${txt('notes','Meter notes',r.notes)}</div>`;
if(t==='meter-reading')return `<div class="form-grid">${opt('meterId','Meter',r.meterId||'',meters)}${inp('readingDate','Reading date',r.readingDate||today(),'date')}${inp('reading','Current reading',r.reading,'number')}${inp('reference','Photo / evidence reference',r.reference)}${txt('notes','Notes',r.notes)}</div>`;
if(t==='vendor')return `<div class="form-grid">${inp('name','Contractor name',r.name)}${opt('trade','Trade',r.trade||'Plumbing',['Electrical','Plumbing','Cleaning','Security','Construction','Fire Safety','Other'])}${inp('phone','Phone / WhatsApp',r.phone)}${inp('email','Email',r.email,'email')}${inp('certExpiry','Certification expiry',r.certExpiry,'date')}${opt('status','Status',r.status||'Active',['Active','Preferred','Inactive'])}${txt('notes','Certification / rate-card notes',r.notes)}</div>`;
if(t==='work')return `<div class="form-grid">${opt('propertyId','Property',r.propertyId||'',properties)}${opt('unitId','Unit (optional)',r.unitId||'',units,'Common area / property work')}${inp('title','Work order title',r.title)}${opt('type','Maintenance type',r.type||'Corrective',['Preventive','Corrective','Emergency'])}${opt('priority','Priority',r.priority||'Normal',['Normal','High','Urgent'])}${opt('vendorId','Contractor',r.vendorId||'',vendors,'Assign later')}${inp('dueDate','Due date',r.dueDate,'date')}${inp('quotedAmount','Approved quote',r.quotedAmount,'number')}${inp('actualCost','Actual cost',r.actualCost,'number')}${opt('status','Workflow status',r.status||'Requested',['Requested','Pending Approval','Approved','Assigned','In Progress','Verification','Closed'])}${txt('notes','Problem, required outcome and verification notes',r.notes)}</div>`;
if(t==='inspection')return `<div class="form-grid">${opt('propertyId','Property',r.propertyId||'',properties)}${opt('unitId','Unit (optional)',r.unitId||'',units,'Property-wide inspection')}${opt('type','Inspection type',r.type||'Routine',['Move-In','Routine','Renewal','Exit','Fire Safety','Health & Safety','Building Compliance','Defect Assessment','Quality Verification'])}${inp('date','Inspection date',r.date||today(),'date')}${inp('inspector','Inspector',r.inspector)}${opt('conditionRating','Overall rating',r.conditionRating||'',['Excellent','Good','Fair','Poor','Critical'])}${opt('status','Status',r.status||'Scheduled',['Scheduled','In Progress','Completed','Overdue','Closed'])}${inp('gpsLat','Latitude',r.gpsLat)}${inp('gpsLon','Longitude',r.gpsLon)}${inp('evidenceName','Photo / report reference',r.evidenceName)}${txt('conditionSummary','Checklist: roof, walls, windows, floors, electrical, plumbing, security, fire equipment',r.conditionSummary)}${txt('defects','Defect description, area affected, priority and estimated cost',r.defects)}</div>`;
if(t==='document')return `<div class="form-grid">${opt('propertyId','Property',r.propertyId||'',properties,'No property link')}${opt('leaseId','Agreement',r.leaseId||'',leases,'No agreement link')}${inp('name','Document name',r.name)}${opt('type','Document type',r.type||'Lease Agreement',['Title Deed','Building Plan','Valuation','Lease Agreement','Lease Amendment','Renewal Document','Termination Document','Inspection Report','Maintenance Report','Invoice','Receipt','Statement','Other'])}${opt('status','Status',r.status||'Current',['Draft','Current','Superseded','Archived'])}${inp('expiryDate','Review / expiry date',r.expiryDate,'date')}${inp('fileName','File / private vault reference',r.fileName)}${txt('notes','Notes',r.notes)}</div>`;
if(t==='task')return `<div class="form-grid">${inp('title','Task',r.title)}${inp('date','Due date',r.date||today(),'date')}${opt('priority','Priority',r.priority||'Normal',['Normal','High','Urgent'])}${inp('owner','Assigned to',r.owner)}${opt('status','Status',r.status||'Open',['Open','In Progress','Completed'])}${txt('notes','Notes',r.notes)}</div>`;
if(t==='compliance')return `<div class="form-grid">${opt('propertyId','Property',r.propertyId||'',properties)}${inp('title','Compliance item / finding',r.title)}${opt('category','Category',r.category||'Regulatory',['Regulatory','Internal','Health & Safety','Fire Safety','Building Compliance'])}${inp('dueDate','Review / action due date',r.dueDate,'date')}${opt('status','Status',r.status||'Open',['Open','In Review','Action in Progress','Closed'])}${inp('owner','Action owner',r.owner)}${txt('notes','Finding, control and evidence notes',r.notes)}</div>`;return ''}
const groups={region:'regions',property:'properties',building:'buildings',floor:'floors',unit:'units',contact:'contacts',lease:'leases',renewal:'renewals',termination:'terminations',charge:'charges',payment:'payments',municipal:'municipalAccounts',meter:'meters','meter-reading':'meterReadings',vendor:'vendors',work:'workOrders',inspection:'inspections',document:'documents',task:'tasks',compliance:'complianceItems'};
function openForm(t,id,extra={}){const r=id?find(groups[t],id)||{}:{};$('#modalEyebrow').textContent=t.replaceAll('-',' ').toUpperCase();$('#modalTitle').textContent=`${id?'Edit':'Add'} ${t.replaceAll('-',' ')}`;$('#modalBody').innerHTML=formHtml(t,r,extra);$('#modalForm').dataset.type=t;$('#modalForm').dataset.id=id||'';$('#modal').showModal();if(t==='property')locationAssist();dependentSelects()}
function saveRecord(group,data,id){if(id){const i=state[group].findIndex(x=>x.id===id);state[group][i]={...state[group][i],...data,updatedAt:today()};return state[group][i]}const x={id:uid(group.slice(0,-1)),...data,createdAt:today()};state[group].push(x);return x}
function num(data,keys){keys.forEach(k=>data[k]=Number(data[k]||0))}
async function submit(e){e.preventDefault();const t=e.currentTarget.dataset.type,id=e.currentTarget.dataset.id,data=Object.fromEntries(new FormData(e.currentTarget).entries());if(!t)return; if(t==='property'&&(!data.code||!data.name))return alert('Enter the property code and name.');if(t==='lease'){if(!data.contactId||!data.propertyId||!data.unitId)return alert('Select resident, property and unit.');num(data,['monthlyRent','deposit','escalation','noticeDays']);if(data.status==='Active'){const u=unit(data.unitId);if(u)u.status='Occupied'}}if(t==='charge'){if(!data.leaseId)return alert('Select an agreement.');num(data,['amount'])}if(t==='payment'){if(!data.leaseId||!data.amount)return alert('Select agreement and amount.');num(data,['amount']);data.propertyId=lease(data.leaseId)?.propertyId||''}if(t==='municipal')num(data,['balance']);if(t==='meter-reading'){num(data,['reading']);const previous=state.meterReadings.filter(x=>x.meterId===data.meterId&&x.id!==id).sort((a,b)=>String(b.readingDate).localeCompare(String(a.readingDate)))[0];data.previousReading=previous?.reading||0;data.consumption=Math.max(0,data.reading-data.previousReading)}if(t==='work')num(data,['quotedAmount','actualCost']);if(t==='termination'){num(data,['depositDeduction','finalBalance']);if(data.stage==='Closed'){const l=lease(data.leaseId);if(l){l.status='Terminated';const u=unit(l.unitId);if(u)u.status='Vacant'}}}const saved=saveRecord(groups[t],data,id);if(t==='payment'&&data.chargeId){const amount=Math.min(Number(data.amount),openCharge(find('charges',data.chargeId)));state.allocations.push({id:uid('allocation'),chargeId:data.chargeId,paymentId:saved.id,amount,createdAt:today()})}audit(id?'Record updated':'Record created',`${t}: ${data.name||data.title||data.leaseNo||data.receiptNo||data.accountNo||''}`);save('Saved');$('#modal').close();render()}
function dependentSelects(){const f=$('#modalForm'),p=f.querySelector('[name="propertyId"]'),u=f.querySelector('[name="unitId"]');if(!p||!u)return;const apply=()=>{[...u.options].forEach(o=>{if(!o.value)return;const x=unit(o.value);o.hidden=!!p.value&&x?.propertyId!==p.value});const selected=unit(u.value);if(selected&&p.value&&selected.propertyId!==p.value)u.value=''};p.addEventListener('change',apply);apply()}
function locationAssist(){const input=$('#propertyAddress'),list=$('#addressSuggestions'),locality=$('[name="locality"]'),country=$('[name="country"]'),lat=$('[name="latitude"]'),lon=$('[name="longitude"]');let timer;if(!input)return;const choose=x=>{input.value=x.display_name||input.value;lat.value=x.lat||'';lon.value=x.lon||'';const a=x.address||{};locality.value=a.suburb||a.city_district||a.city||a.town||a.village||locality.value;country.value=a.country||country.value;list.innerHTML=''};input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();list.innerHTML='';if(q.length<3)return;timer=setTimeout(async()=>{try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=5&q=${encodeURIComponent(q)}`,{headers:{'Accept-Language':'en'}});const places=await r.json();list.innerHTML='';places.forEach(x=>{const b=document.createElement('button');b.type='button';b.className='address-choice';b.textContent=x.display_name;b.onclick=()=>choose(x);list.append(b)})}catch{list.innerHTML='<p class="form-help">Address suggestions are unavailable. Enter the address manually.</p>'}},650)});$('#useCurrentLocation').onclick=()=>navigator.geolocation?.getCurrentPosition(async p=>{lat.value=p.coords.latitude.toFixed(6);lon.value=p.coords.longitude.toFixed(6);try{const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&addressdetails=1&lat=${lat.value}&lon=${lon.value}`,{headers:{'Accept-Language':'en'}});choose(await r.json())}catch{input.value=`${lat.value}, ${lon.value}`}},()=>alert('Allow location access or enter the address manually.'),{enableHighAccuracy:true,timeout:10000})}
function receipt(id){const p=find('payments',id),l=lease(p?.leaseId),c=contact(l?.contactId);if(!p)return;const w=window.open('','_blank');w.document.write(`<title>Receipt ${esc(p.receiptNo)}</title><style>body{font-family:Arial;padding:35px;color:#12395f}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #ddd;padding:10px;text-align:left}</style><h1>Musa Business Management CC</h1><p>MBM payment receipt</p><table><tr><th>Receipt</th><td>${esc(p.receiptNo)}</td></tr><tr><th>Resident</th><td>${esc(c?.name)}</td></tr><tr><th>Agreement</th><td>${esc(leaseName(p.leaseId))}</td></tr><tr><th>Date</th><td>${date(p.paymentDate)}</td></tr><tr><th>Method</th><td>${esc(p.method)}</td></tr><tr><th>Amount</th><td>${money(p.amount)}</td></tr></table>`);w.document.close();w.print()}
function whatsApp(id){const p=find('payments',id),l=lease(p?.leaseId),c=contact(l?.contactId);if(!c?.phone)return alert('Record a resident contact number first.');const n=String(c.phone).replace(/\D/g,'').replace(/^0/,'264'),message=`Hello ${c.name}, MBM confirms receipt ${p.receiptNo} for ${money(p.amount)} on ${date(p.paymentDate)}. Thank you.`;window.open(`https://wa.me/${n}?text=${encodeURIComponent(message)}`,'_blank','noopener')}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function backup(){audit('Backup downloaded','MBM V12 workspace JSON exported.');save();download(`MBM-V12-backup-${today()}.json`,JSON.stringify(state,null,2))}
function exportReport(){const r=state.ui.report||'portfolio',scope=state.ui.reportScope,rows=[['MBM report',r],['Scope',scope?propertyName(scope):'Entire portfolio'],['Generated',new Date().toLocaleString('en-NA')],[]];if(r==='portfolio'){rows.push(['Property','Buildings','Units','Occupied','Vacant']);state.properties.filter(p=>!scope||p.id===scope).forEach(p=>{const u=state.units.filter(x=>x.propertyId===p.id);rows.push([propertyName(p.id),state.buildings.filter(b=>b.propertyId===p.id).length,u.length,u.filter(x=>x.status==='Occupied').length,u.filter(x=>x.status==='Vacant').length])})}else if(r==='revenue'){rows.push(['Agreement','Charge','Payment','Open']);state.leases.filter(l=>!scope||l.propertyId===scope).forEach(l=>rows.push([leaseName(l.id),state.charges.filter(c=>c.leaseId===l.id).reduce((s,c)=>s+Number(c.amount||0),0),state.payments.filter(p=>p.leaseId===l.id).reduce((s,p)=>s+Number(p.amount||0),0),openCharges().filter(c=>c.leaseId===l.id).reduce((s,c)=>s+openCharge(c),0)]))}else{rows.push(['Property','Metric','Value']);state.properties.filter(p=>!scope||p.id===scope).forEach(p=>rows.push([propertyName(p.id),'Municipal balance',state.municipalAccounts.filter(m=>m.propertyId===p.id).reduce((s,m)=>s+Number(m.balance||0),0)]))}download(`MBM-${r}-${today()}.csv`,rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv')}
function advanceWork(id){const w=find('workOrders',id),flow=['Requested','Pending Approval','Approved','Assigned','In Progress','Verification','Closed'];if(!w)return;w.status=flow[Math.min(flow.indexOf(w.status)+1,flow.length-1)];audit('Work order advanced',`${w.title} → ${w.status}`);save('Work order advanced');render()}
function defectWork(id){const i=find('inspections',id);if(!i?.defects)return alert('Record a defect on the inspection before creating a work order.');const w={id:uid('workOrder'),propertyId:i.propertyId,unitId:i.unitId,title:`Inspection defect: ${i.type}`,type:'Corrective',priority:/critical|urgent/i.test(i.defects)?'Urgent':'High',status:'Requested',dueDate:i.date,notes:i.defects,quotedAmount:0,actualCost:0,createdAt:today()};state.workOrders.push(w);audit('Work order created from inspection',w.title);save('Defect work order created');render()}
function map(id){const p=prop(id);if(!p)return;const url=p.latitude&&p.longitude?`https://www.openstreetmap.org/?mlat=${encodeURIComponent(p.latitude)}&mlon=${encodeURIComponent(p.longitude)}#map=17/${encodeURIComponent(p.latitude)}/${encodeURIComponent(p.longitude)}`:`https://www.openstreetmap.org/search?query=${encodeURIComponent(p.address||p.name)}`;window.open(url,'_blank','noopener')}
function wireFilters(){$('#propertyScope')?.addEventListener('change',e=>{state.ui.propertyId=e.target.value;save();render()});$('#reportScope')?.addEventListener('change',e=>{state.ui.reportScope=e.target.value;save();render()})}
function search(q){const out=$('#searchResults'),term=q.trim().toLowerCase();if(!term){out.hidden=true;return}const list=[];const add=(view,type,title,detail,keys='')=>list.push({view,type,title,detail,keys:`${title} ${detail} ${keys}`.toLowerCase()});state.properties.forEach(x=>add('portfolio','Property',propertyName(x.id),x.address,`${x.erf} ${x.locality}`));state.units.forEach(x=>add('portfolio','Unit',x.name,propertyName(x.propertyId),x.status));state.contacts.forEach(x=>add('occupancy','Contact',x.name,`${x.role} ${x.phone||''}`,x.email));state.leases.forEach(x=>add('occupancy','Agreement',leaseName(x.id),`${propertyName(x.propertyId)} ${unitName(x.unitId)}`,x.status));state.payments.forEach(x=>add('finance','Receipt',x.receiptNo,`${leaseName(x.leaseId)} ${money(x.amount)}`,x.method));state.workOrders.forEach(x=>add('operations','Work order',x.title,propertyName(x.propertyId),`${x.status} ${x.priority}`));state.documents.forEach(x=>add('control','Document',x.name,x.type,x.status));const intents={overdue:['overdue','arrears','expiry'],renewal:['agreement','expiry','renewal'],municipal:['municipal','water','electricity'],maintenance:['work','inspection'],vacant:['vacant']};let matches=intents[term]?list.filter(x=>intents[term].some(k=>x.keys.includes(k))):list.filter(x=>term.split(/\s+/).every(k=>x.keys.includes(k)));out.innerHTML=matches.slice(0,10).map(x=>`<button class="search-result" data-search-view="${x.view}"><span class="result-kind">${esc(x.type)}</span><span><b>${esc(x.title)}</b><small>${esc(x.detail)}</small></span><i>Open →</i></button>`).join('')||'<div class="search-empty">No records found. Try an address, person, receipt, “overdue”, “renewal”, “municipal” or “maintenance”.</div>';out.hidden=false}
function answer(q){q=q.toLowerCase();if(/arrear|debt|receipt|payment/.test(q))return `Open billed debt is ${money(openCharges().reduce((s,c)=>s+openCharge(c),0))} across ${openCharges().length} charge(s).`;if(/municipal|water|electric/.test(q))return `Municipal balance is ${money(municipal())} across ${state.municipalAccounts.length} account(s), with ${state.meters.length} registered meter(s).`;if(/renew|expiry|agreement|lease/.test(q)){const x=activeLeases().filter(l=>l.endDate&&days(l.endDate)<=90);return `${x.length} active agreement(s) expire within 90 days.${x[0]?` Next: ${leaseName(x[0].id)} in ${days(x[0].endDate)} days.`:''}`}if(/work|maint|inspection|service/.test(q))return `${state.workOrders.filter(w=>w.status!=='Closed').length} work order(s) remain open and ${state.inspections.filter(i=>!['Completed','Closed'].includes(i.status)).length} inspection(s) need attention.`;if(/vacan|occup/.test(q))return `${state.units.filter(u=>u.status==='Vacant').length} unit(s) are vacant; ${activeLeases().length} agreement(s) are active.`;return `${issues().length} control item(s) require review. Ask about arrears, municipal balance, expiring agreements, maintenance or vacancies.`}
$('#modalForm').addEventListener('submit',submit);$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){state.ui.view=b.dataset.view;save();render();$('#sidebar').classList.remove('open')}});$('#menuButton').onclick=()=>$('#sidebar').classList.toggle('open');$('#quickAdd').onclick=()=>openForm('lease');$('#backupButton').onclick=backup;
$('#app').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){state.ui.view=b.dataset.view;save();render();return}if(b.dataset.report){state.ui.report=b.dataset.report;save();render();return}const a=b.dataset.action;if(a==='form')return openForm(b.dataset.type,b.dataset.id,{propertyId:b.dataset.property,leaseId:b.dataset.lease});if(a==='select-property'){state.ui.propertyId=b.dataset.id;save();render();return}if(a==='map')return map(b.dataset.id);if(a==='receipt')return receipt(b.dataset.id);if(a==='whatsapp')return whatsApp(b.dataset.id);if(a==='advance-work')return advanceWork(b.dataset.id);if(a==='defect-work')return defectWork(b.dataset.id);if(a==='backup')return backup();if(a==='export-report')return exportReport();if(a==='cloud-signin')return window.MBMCloudV10?.signIn();if(a==='cloud-signup')return window.MBMCloudV10?.signUp();if(a==='cloud-save')return window.MBMCloudV10?.save();if(a==='cloud-load')return window.MBMCloudV10?.load();if(a==='import')return $('#importFile').click()});
$('#globalSearch').addEventListener('input',e=>search(e.target.value));$('#clearSearch').onclick=()=>{$('#globalSearch').value='';search('')};$('#searchResults').onclick=e=>{const b=e.target.closest('[data-search-view]');if(b){state.ui.view=b.dataset.searchView;$('#globalSearch').value='';$('#searchResults').hidden=true;save();render()}};document.addEventListener('click',e=>{if(!e.target.closest('.smart-search'))$('#searchResults').hidden=true});
$('#manualButton').onclick=()=>$('#manualDialog').showModal();$('#closeManual').onclick=()=>$('#manualDialog').close();$('#assistantButton').onclick=()=>$('#assistantDialog').showModal();$('#closeAssistant').onclick=()=>$('#assistantDialog').close();$('#askAssistant').onclick=()=>$('#assistantAnswer').textContent=answer($('#assistantQuestion').value);$('#assistantQuestion').addEventListener('keydown',e=>{if(e.key==='Enter'){$('#askAssistant').click();e.preventDefault()}});
$('#importFile').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{state=Object.assign(blank(),JSON.parse(r.result),{version:12});audit('Backup imported','MBM workspace restored from JSON backup.');save('Backup imported');render()}catch{alert('This is not a valid MBM backup.')}};r.readAsText(f);e.target.value=''});
window.MBMWorkspace={getState:()=>state,replaceState:x=>{state=Object.assign(blank(),x,{version:12});audit('Cloud backup loaded','MBM workspace restored from private cloud backup.');save('Cloud backup loaded');render()}};const h=location.hash.slice(1);if(VIEWS.includes(h))state.ui.view=h;render();
})();
